import java.text.DecimalFormat;
import java.util.Scanner;
public class JWinPercentageInput {
	public static void main(String[] args) {
		//Khatwa 1: Qira'at 'adad al-mubarayat fi al-botola
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil 'adad al-mubarayat fi al-botola: ");
		int totalGames = scan.nextInt();		
		//Khatwa 2: Tahaqquq min sihat madkhal almustakhdim li'adad al-mubarayat fi al-botola, itlub madkhalan salihan madha la yadkhul almustakhdim raqam ghayr salih; 'illa an yatanahaa
		while ( totalGames <= 0 ) {
			System.out.println("Adkhil 'adad al-mubarayat fi al-botola: ");
			totalGames = scan.nextInt();
		}
		//Khatwa 3: Qira'at 'adad al-mubarayat allati fazaha al-fariq fi al-botola
		System.out.println("Adkhil 'adad al-mubarayat allati fazaha al-fariq fi al-botola: ");
		int wins = scan.nextInt();		
		//Khatwa 4: Tahaqquq min sihat madkhal almustakhdim li'adad al-mubarayat allati fazaha al-fariq, itlub madkhalan salihan madha la yadkhul almustakhdim raqam ghayr salih; 'illa an yatanahaa
		while ( wins < 0 || wins > totalGames ) {
			System.out.println("Adkhil 'adad al-mubarayat allati fazaha al-fariq fi al-botola: ");
			wins = scan.nextInt();
		}
		scan.close();
		//Khatwa 5: Tahsib wa tatba' nisbat al-mubarayat al-mufooza li al-fariq
		double ratio = (double) wins / totalGames;
		DecimalFormat fmt = new DecimalFormat("0.###");
		System.out.println("Nisbat al-fawz:" + fmt.format(ratio));
	}
}
